void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord / iResolution.xy;

    float value = uv.x;

    float lower_band_min = 0.0;
    float lower_band_max = 0.4;
    float upper_band_min = 0.6;
    float upper_band_max = 1.0;

    vec3 lower_color_start = vec3(0.0, 0.0, 1.0); // Blue
    vec3 lower_color_end   = vec3(0.0, 1.0, 1.0); // Cyan
    vec3 upper_color_start = vec3(1.0, 1.0, 0.0); // Yellow
    vec3 upper_color_end   = vec3(1.0, 0.0, 0.0); // Red

    vec3 color = vec3(0.0);
    float alpha = 0.0;

    if (value >= lower_band_min && value <= lower_band_max) {
        float t = (value - lower_band_min) / (lower_band_max - lower_band_min);
        color = mix(lower_color_start, lower_color_end, t);
        alpha = 1.0;
    } 
    else if (value >= upper_band_min && value <= upper_band_max) {
        float t = (value - upper_band_min) / (upper_band_max - upper_band_min);
        color = mix(upper_color_start, upper_color_end, t);
        alpha = 1.0;
    }

    fragColor = vec4(color, alpha);
}
